public static DataTable GetAvailableWebSchedTimeSlots(long recallNum, DateTime dateStart, DateTime dateEnd) {
    // No need to check RemotingRole; no call to db.
    Clinic clinic = Clinics.GetClinicForRecall(recallNum);
    Recall recall = GetRecall(recallNum);
    if (recall == null) {
        throw new ODException(Lans.g("WebSched", "The recall appointment you are trying to schedule is no longer available. Please call us to schedule your appointment."));
    }

    // Get the RecallType associated with the recall
    RecallType recallType = RecallTypeC.GetListt().FirstOrDefault(x => x.RecallTypeNum == recall.RecallTypeNum);

    // Get all the Operatories that are flagged for Web Sched
    List<Operatory> listWebSchedOps = Operatories.GetOpsForWebSched();
    List<long> listWebSchedOpNums = listWebSchedOps.Select(x => x.OperatoryNum).Distinct().ToList();

    if (listWebSchedOpNums.Count < 1) {
        throw new ODException(Lans.g("WebSched", "There are no operatories set up for Web Sched. Please call us to schedule your appointment."));
    }

    // Get the available time slots based on the recall type
    DataTable tableSchedules = Schedules.GetSchedulesAndBlockoutsForWebSched(listWebSchedOpNums, dateStart, dateEnd);
    List<Schedule> listAllSchedules = Crud.ScheduleCrud.TableToList(tableSchedules);
    List<Schedule> listProviderSchedules = listAllSchedules.FindAll(x => x.BlockoutType == 0);

    // Create a custom table to store available time slots
    DataTable tableAvailableTimes = new DataTable();
    tableAvailableTimes.Columns.Add("SchedDate");
    tableAvailableTimes.Columns.Add("TimeStart");
    tableAvailableTimes.Columns.Add("TimeStop");
    tableAvailableTimes.Columns.Add("OperatoryNum");

    List<TimeSlot> listTimeSlots = new List<TimeSlot>();

    // Find all available time slots
    DateTime dateLastTimeSlot = new DateTime(1800, 1, 1);
    int apptLengthMins = RecallTypes.ConvertTimePattern(recallType.TimePattern).Length * 5;

    // Check if there are any available time slots
    if (listProviderSchedules != null && listProviderSchedules.Count > 0) {
        // Get the time slots for each provider
        Dictionary<DateTime, List<ApptSearchProviderSchedule>> dictProvSchedules = Appointments.GetApptSearchProviderScheduleForProvidersAndDate(
            listProvNums, dateStart, dateEnd, listProviderSchedules, listApptsForOps);

        // Create a list of available time slots
        foreach (var schedule in listProviderSchedules) {
            DateTime timeStart = schedule.TimeStart;
            DateTime timeStop = schedule.TimeStop;
            long operatoryNum = schedule.OperatoryNum;

            // Check if the time is within the date range
            if (timeStart <= dateEnd && timeStop >= dateStart) {
                // Add the time slot to the list
                listTimeSlots.Add(new TimeSlot {
                    SchedDate = schedule.Date,
                    TimeStart = timeStart,
                    TimeStop = timeStop,
                    OperatoryNum = operatoryNum
                });
            }
        }

        // Add the time slots to the available time slots table
        tableAvailableTimes.Rows.Add(listTimeSlots);
    }

    return tableAvailableTimes;
}
