    /**
     * Internal method to read DHT marker
     * @param is Input. Ignored if lenAvailable &gt; 0
     * @param lenAvailable Length of marker data read into data array. Passed as
     * 0 if marker is to be read first.
     */
    protected int readDHT(InputStream is, int lenAvailable) throws IOException {
        int result = lenAvailable;
        if(result <= 0)
            result = readMarker(is);
        int base = 0;
        do {
            boolean is_ac = (data[base] & 255) > 15;
            int tbl_ix;
            if (is_ac)
                tbl_ix = (data[base] & 255)-16;
            else
                tbl_ix = 0;
            int size = 1 + 16 + ac_huffval[tbl_ix].length;
            int next_base = base + size;
            if (next_base > lenAvailable) {
                result = next_base;
                break;
            }
            base = next_base;
        } while (true);
        return result;
    }
